SourceCode.Declaration:
internal class UPSPricingRuleBuilder_RuleLine extends UPSPricingRuleBuilder
{
    private UPSRuleTable ruleTable;

}

Method.Source:
public static void main(Args args)
{
    UPSPricingRuleBuilder_RuleLine createRule;
    createRule = new UPSPricingRuleBuilder_RuleLine(args.record());

    createRule.createRecord();
}

public void initMasterRecord()
{
    UPSRuleLine ruleLine;

    ruleLine.clear();
    ruleLine.RuleId = this.ruleTable.RuleId;
    ruleLine.LineNum = UPSRuleLine::lastLineNum(ruleLine.RuleId) + SystemParameters::getSystemLineNumberIncrement();

    this.masterRecord = ruleLine;
}

public void linkPricingRule(UPSPricingRule _pricingRule)
{
    if (this.dialogOk && _pricingRule)
    {
        UPSRuleLine createdRuleLine = masterRecord;

        createdRuleLine.LinePricingRule = _pricingRule.RecId;
    }
}
